+pub(crate) struct SubtreeVectors<'a> {
+    vectors: pci::IrqVectorRegistration<'a>,
+    /// Every subtree nova-core services.
+    serviced: SubtreeSet,
+    /// The type [`alloc_vectors`] obtained, which fixes both the entry each subtree raises and the
